<?php
final class SalesService {
    private PDO $pdo; private CollectionStore $store;
    public function __construct(PDO $pdo,CollectionStore $store){$this->pdo=$pdo;$this->store=$store;}
    private function now(): string{return date(DATE_ATOM);} private function id(string $p): string{return $p.'-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,8));}
    private function nextNumber(): string {
        $prefix='PJL-'.date('Ymd').'-';$sales=$this->store->get('penjualan');$max=0;foreach($sales as $s){$n=(string)($s['no_penjualan']??'');if(str_starts_with($n,$prefix)){$x=(int)substr($n,-4);$max=max($max,$x);}}return $prefix.str_pad((string)($max+1),4,'0',STR_PAD_LEFT);
    }
    private static function stockKey(array $x): array{return ['id_stok_item'=>(string)($x['id_stok_item']??''),'kode_sku'=>(string)($x['kode_sku']??$x['sku_varian']??$x['kode']??''),'id_produk'=>(string)($x['id_produk']??$x['id']??'')];}
    private function find(array $arr,array $key): int {
        foreach(['id_stok_item'=>['id_stok_item'],'kode_sku'=>['kode_sku','sku_varian','kode'],'id_produk'=>['id_produk','id']] as $field=>$aliases){if(($key[$field]??'')==='')continue;foreach($arr as $i=>$r)foreach($aliases as $alias)if(isset($r[$alias])&&strcasecmp((string)$r[$alias],(string)$key[$field])===0)return $i;return -1;}return -1;
    }
    private function upsertSale(array &$sales,array $record): void {$id=(string)($record['id_penjualan']??'');foreach($sales as $i=>$s)if((string)($s['id_penjualan']??'')===$id){$sales[$i]=array_merge($s,$record);return;}array_unshift($sales,$record);}
    public function saveDraft(array $p): array {
        $sales=$this->store->get('penjualan');$itemsTbl=$this->store->get('penjualan_item');$id=(string)($p['id_penjualan']??'');if($id==='')$id=$this->id('SALE');foreach($sales as $old)if((string)($old['id_penjualan']??'')===$id&&strtoupper((string)($old['status_transaksi']??''))!=='DRAFT')throw new DomainException('Penjualan terposting tidak dapat dijadikan draft.',409);$no=(string)($p['no_penjualan']??'');if($no==='')$no='DRAFT-'.date('Ymd-His');$rec=array_merge($p,['id_penjualan'=>$id,'no_penjualan'=>$no,'status_transaksi'=>'DRAFT','created_at'=>$p['created_at']??$this->now(),'updated_at'=>$this->now()]);$this->upsertSale($sales,$rec);$itemsTbl=array_values(array_filter($itemsTbl,fn($x)=>(string)($x['id_penjualan']??'')!==$id));foreach((array)($p['items']??[]) as $i=>$it)$itemsTbl[]=array_merge($it,['id_item'=>$it['id_item']??$this->id('SLI'),'id_penjualan'=>$id,'no_penjualan'=>$no,'created_at'=>$this->now()]);$this->store->putMany(['penjualan'=>$sales,'penjualan_item'=>$itemsTbl]);AuditService::log($this->pdo,'SAVE_SALE_DRAFT','Penjualan',$id,$no,null,$rec);return ['status'=>'success','message'=>'Draft penjualan tersimpan.','data'=>$rec];
    }
    public function post(array $p): array {
        $lock='jago_laba_sales';$q=$this->pdo->prepare('SELECT GET_LOCK(?,10)');$q->execute([$lock]);if((int)$q->fetchColumn()!==1)throw new RuntimeException('Transaksi penjualan sedang diproses.');
