            $prepared=[];$totalQty=0;$subCents=0;$discountCents=0;$hppCents=0;$hppComplete=true;
            foreach($items as $i=>$it){$qty=(float)($it['qty']??0);if(!is_finite($qty)||$qty<=0||floor($qty)!==$qty)throw new RuntimeException('Qty item #'.($i+1).' harus lebih dari 0.');$key=self::stockKey($it);$mi=$this->find($master,$key);$pi=$this->find($produk,$key);if($mi<0){if($pi<0)throw new RuntimeException('SKU produk tidak ditemukan: '.($key['kode_sku']?:$key['id_produk']));$master[]=['id_stok_item'=>$produk[$pi]['id_stok_item']??('STK-'.strtoupper(substr(bin2hex(random_bytes(6)),0,10))),'id_produk'=>$produk[$pi]['id']??'','kode_sku'=>$produk[$pi]['kode']??'','nama_produk'=>$produk[$pi]['nama']??'','stok_awal'=>(float)($produk[$pi]['stok']??0),'masuk_jahit'=>0,'masuk_vendor'=>0,'keluar_penjualan'=>0,'stok_akhir'=>(float)($produk[$pi]['stok']??0),'status_stok'=>'Aman'];$mi=count($master)-1;}
                $before=(float)($master[$mi]['stok_akhir']??$master[$mi]['stok']??0);if($qty>$before)throw new RuntimeException('Stok tidak mencukupi untuk '.($it['nama_produk']??$key['kode_sku']).'. Tersedia '.$before.', diminta '.$qty);$unit=(float)($it['harga_jual']??0);$discount=(float)($it['diskon_item']??0);if(!is_finite($unit)||!is_finite($discount)||$unit<0||$discount<0||$discount>$unit*$qty)throw new InvalidArgumentException('Harga atau diskon item tidak valid.');
                $lineCents=(int)round($unit*100)*$qty;$subCents+=$lineCents;$discountCents+=(int)round($discount*100);
                $unitHpp=$pi>=0?($produk[$pi]['hpp_produk']??null):null;if($unitHpp===null||!is_numeric($unitHpp)||$unitHpp<=0){$hppComplete=false;$items[$i]['hpp_satuan']=null;}else{$items[$i]['hpp_satuan']=(float)$unitHpp;$hppCents+=(int)round((float)$unitHpp*100)*$qty;}
                $items[$i]['subtotal']=($lineCents-(int)round($discount*100))/100;
                $prepared[]=[$i,$mi,$pi,$before,$before-$qty];$master[$mi]['stok_akhir']=$before-$qty;$master[$mi]['stok']=$before-$qty;$totalQty+=$qty;}
            foreach(['diskon_transaksi','ongkir','biaya_lain','nominal_dibayar'] as $f)if(isset($p[$f])&&(!is_numeric($p[$f])||!is_finite((float)$p[$f])||(float)$p[$f]<0))throw new InvalidArgumentException('Nominal penjualan tidak valid.');
            $goodsCents=$subCents-$discountCents-(int)round((float)($p['diskon_transaksi']??0)*100);if($goodsCents<0)throw new InvalidArgumentException('Diskon transaksi melebihi nilai barang.');
            $billCents=$goodsCents+(int)round((float)($p['ongkir']??0)*100)+(int)round((float)($p['biaya_lain']??0)*100);$tendered=(int)round((float)($p['nominal_dibayar']??0)*100);
            $p['items']=$items;$p['subtotal']=$subCents/100;$p['diskon_item_total']=$discountCents/100;$p['total_tagihan']=$billCents/100;$p['total_qty']=$totalQty;$p['uang_diterima']=$tendered/100;$p['nominal_dibayar']=min($tendered,$billCents)/100;$p['kembalian']=max(0,$tendered-$billCents)/100;$p['sisa_tagihan']=max(0,$billCents-$tendered)/100;$p['total_hpp']=$hppComplete?$hppCents/100:null;$p['laba_kotor']=$hppComplete?($goodsCents-$hppCents)/100:null;$p['margin_persen']=$hppComplete&&$goodsCents>0?round(($goodsCents-$hppCents)/$goodsCents*100,2):null;$p['hpp_source']='product_standard_snapshot';
            if($p['nominal_dibayar']>0&&empty($p['id_rekening']))throw new InvalidArgumentException('Rekening penerimaan wajib dipilih.');
            foreach($prepared as [$i,$mi,$pi,$before,$after]){$it=$items[$i];$qty=(float)$it['qty'];$master[$mi]['stok_akhir']=$after;$master[$mi]['stok']=$after;$master[$mi]['keluar_penjualan']=(float)($master[$mi]['keluar_penjualan']??0)+$qty;$master[$mi]['last_updated']=$this->now();$min=(float)($master[$mi]['stok_minimum']??0);$master[$mi]['status_stok']=$after<=0?'Habis':($after<=$min?'Menipis':'Aman');if($pi>=0){$produk[$pi]['stok']=$after;$produk[$pi]['updated_at']=$this->now();}$mut[]=['id_mutasi'=>$this->id('MUT'),'tanggal'=>$p['tanggal']??date('Y-m-d'),'waktu'=>date('H:i:s'),'jenis_mutasi'=>'OUT_SALE','id_stok_item'=>$master[$mi]['id_stok_item']??($it['id_stok_item']??''),'id_produk'=>$master[$mi]['id_produk']??($it['id_produk']??''),'kode_sku'=>$master[$mi]['kode_sku']??($it['kode_sku']??''),'qty_masuk'=>0,'qty_keluar'=>$qty,'stok_sebelum'=>$before,'stok_setelah'=>$after,'saldo_berjalan'=>$after,'sumber_modul'=>'PENJUALAN','id_referensi'=>$id,'no_referensi'=>$no,'idempotency_key'=>'STOCK|SALE|'.$id.'|'.$i,'operator'=>$p['operator']??($_SESSION['username']??'system'),'created_at'=>$this->now()];}
            $rec=array_merge($p,['id_penjualan'=>$id,'no_penjualan'=>$no,'status_transaksi'=>'POSTED','total_qty'=>$p['total_qty']??$totalQty,'posted_at'=>$this->now(),'posted_by'=>$p['operator']??($_SESSION['username']??'system'),'updated_at'=>$this->now(),'created_at'=>$p['created_at']??$this->now(),'idempotency_key'=>$idem,'backup_status'=>'PENDING']);$this->upsertSale($sales,$rec);$itemsTbl=array_values(array_filter($itemsTbl,fn($x)=>(string)($x['id_penjualan']??'')!==$id));foreach($items as $i=>$it)$itemsTbl[]=array_merge($it,['id_item'=>$it['id_item']??$this->id('SLI'),'id_penjualan'=>$id,'no_penjualan'=>$no,'stok_sebelum'=>$prepared[$i][3]??null,'stok_setelah'=>$prepared[$i][4]??null,'created_at'=>$this->now()]);$paid=(float)($p['nominal_dibayar']??0);if($paid>0)$keu[]=['id'=>$this->id('K'),'tanggal'=>$p['tanggal']??date('Y-m-d'),'tipe'=>'Masuk','nominal'=>$paid,'kategori'=>'Penjualan Hasil Produksi','modul'=>'Penjualan','id_rekening'=>$p['id_rekening']??'','id_referensi'=>$id,'no_referensi'=>$no,'idempotency_key'=>'FINANCE|SALE|'.$id,'keterangan'=>'Penjualan '.$no,'created_at'=>$this->now(),'created_by'=>$p['operator']??($_SESSION['username']??'system')];
            $this->store->putMany(['penjualan'=>$sales,'penjualan_item'=>$itemsTbl,'master_stok'=>$master,'produk'=>$produk,'mutasi_stok'=>$mut,'keuangan'=>$keu]);AuditService::log($this->pdo,'POST_SALE','Penjualan',$id,$no,null,$rec);return ['status'=>'success','code'=>'SALE_POSTED','message'=>'Penjualan berhasil diposting.','data'=>$rec,'stock'=>['posted'=>true],'finance'=>['posted'=>$paid>0]];
        }finally{$r=$this->pdo->prepare('SELECT RELEASE_LOCK(?)');$r->execute([$lock]);}
    }
    public function correct(array $p): array {
        $id=(string)($p['id_penjualan']??'');if($id==='')throw new RuntimeException('ID penjualan tidak valid.');$sales=$this->store->get('penjualan');$corr=$this->store->get('penjualan_koreksi');$idx=-1;foreach($sales as $i=>$s)if((string)($s['id_penjualan']??'')===$id){$idx=$i;break;}if($idx<0)throw new RuntimeException('Penjualan tidak ditemukan.');$before=$sales[$idx];if(strtoupper((string)($before['status_transaksi']??''))==='POSTED'){foreach(['items','nominal_dibayar','id_rekening','total_harga','total_tagihan','total_qty','status_transaksi','id_penjualan','no_penjualan','tanggal'] as $field)if(array_key_exists($field,$p)&&($p[$field]??null)!==($before[$field]??null))throw new DomainException('Perubahan nilai, barang, tanggal atau rekening wajib melalui reversal dan posting ulang.',409);}$rev=count(array_filter($corr,fn($x)=>(string)($x['id_penjualan']??'')===$id))+1;$revNo='R'.str_pad((string)$rev,2,'0',STR_PAD_LEFT);$after=array_merge($before,$p,['updated_at'=>$this->now(),'revision_no'=>$revNo,'last_correction_at'=>$this->now(),'pdf_needs_refresh'=>true]);$sales[$idx]=$after;$row=['id_koreksi'=>$this->id('CORR'),'id_penjualan'=>$id,'no_penjualan'=>$after['no_penjualan']??'','revision_no'=>$revNo,'tanggal_koreksi'=>$this->now(),'alasan'=>$p['alasan_koreksi']??$p['alasan']??'Koreksi Admin','before_json'=>json_encode($before,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'after_json'=>json_encode($after,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'operator'=>$p['operator']??($_SESSION['username']??'system'),'created_at'=>$this->now()];$corr[]=$row;$this->store->putMany(['penjualan'=>$sales,'penjualan_koreksi'=>$corr]);AuditService::log($this->pdo,'CORRECT_SALE','Penjualan',$id,$after['no_penjualan']??'', $before,$after);return ['status'=>'success','message'=>'Koreksi penjualan tersimpan. Untuk perubahan qty/akun besar gunakan VOID + posting ulang agar ledger tetap eksplisit.','data'=>['revision_no'=>$revNo,'correction'=>$row]];
    }
    public function void(array $p): array {
        $id=(string)($p['id_penjualan']??'');$sales=$this->store->get('penjualan');$items=$this->store->get('penjualan_item');$master=$this->store->get('master_stok');$produk=$this->store->get('produk');$mut=$this->store->get('mutasi_stok');$keu=$this->store->get('keuangan');$idx=-1;foreach($sales as $i=>$s)if((string)($s['id_penjualan']??'')===$id){$idx=$i;break;}if($idx<0)throw new RuntimeException('Penjualan tidak ditemukan.');if(strtoupper((string)($sales[$idx]['status_transaksi']??''))==='DRAFT')throw new DomainException('Draft belum memiliki stok atau pembayaran untuk dibalik.');if(strtoupper((string)($sales[$idx]['status_transaksi']??''))==='VOID')return ['status'=>'success','code'=>'DUPLICATE_IGNORED','data'=>$sales[$idx]];$saleItems=array_values(array_filter($items,fn($x)=>(string)($x['id_penjualan']??'')===$id));foreach($saleItems as $i=>$it){$key=self::stockKey($it);$mi=$this->find($master,$key);$pi=$this->find($produk,$key);if($mi<0)throw new RuntimeException('Stok sumber pembalikan tidak ditemukan. Proses dibatalkan.');$qty=(float)($it['qty']??0);$before=(float)($master[$mi]['stok_akhir']??0);$after=$before+$qty;$master[$mi]['stok_akhir']=$after;$master[$mi]['stok']=$after;$master[$mi]['keluar_penjualan']=max(0,(float)($master[$mi]['keluar_penjualan']??0)-$qty);if($pi>=0)$produk[$pi]['stok']=$after;$mut[]=['id_mutasi'=>$this->id('MUT'),'tanggal'=>date('Y-m-d'),'waktu'=>date('H:i:s'),'jenis_mutasi'=>'SALE_VOID_IN','id_stok_item'=>$master[$mi]['id_stok_item']??'','id_produk'=>$master[$mi]['id_produk']??'','kode_sku'=>$master[$mi]['kode_sku']??'','qty_masuk'=>$qty,'qty_keluar'=>0,'stok_sebelum'=>$before,'stok_setelah'=>$after,'saldo_berjalan'=>$after,'sumber_modul'=>'PENJUALAN_VOID','id_referensi'=>$id,'no_referensi'=>$sales[$idx]['no_penjualan']??'','operator'=>$p['operator']??($_SESSION['username']??'system'),'created_at'=>$this->now()];}
        $paid=(float)($sales[$idx]['nominal_dibayar']??0);if($paid>0)$keu[]=['id'=>$this->id('K'),'tanggal'=>date('Y-m-d'),'tipe'=>'Keluar','nominal'=>$paid,'kategori'=>'Reversal Penjualan','modul'=>'Penjualan','id_rekening'=>$sales[$idx]['id_rekening']??'','id_referensi'=>$id,'no_referensi'=>$sales[$idx]['no_penjualan']??'','idempotency_key'=>'FINANCE|VOID|'.$id,'keterangan'=>'VOID '.$sales[$idx]['no_penjualan'],'created_at'=>$this->now(),'created_by'=>$p['operator']??($_SESSION['username']??'system')];$sales[$idx]['status_transaksi']='VOID';$sales[$idx]['void_reason']=$p['void_reason']??'Pembatalan';$sales[$idx]['void_at']=$this->now();$sales[$idx]['void_by']=$p['operator']??($_SESSION['username']??'system');$this->store->putMany(['penjualan'=>$sales,'master_stok'=>$master,'produk'=>$produk,'mutasi_stok'=>$mut,'keuangan'=>$keu]);AuditService::log($this->pdo,'VOID_SALE','Penjualan',$id,$sales[$idx]['no_penjualan']??'',null,$sales[$idx]);return ['status'=>'success','message'=>'Penjualan berhasil di-VOID.','data'=>$sales[$idx]];
    }
    public function retryBackup(array $p): array { $id=(string)($p['id_penjualan']??'');$sales=$this->store->get('penjualan');foreach($sales as &$s)if((string)($s['id_penjualan']??'')===$id){$s['backup_status']='PENDING';$s['backup_at']=$this->now();$this->store->put('penjualan',$sales);return ['status'=>'success','message'=>'Status backup transaksi dijadwalkan ulang.','data'=>$s];}throw new RuntimeException('Penjualan tidak ditemukan.');}
